    es: { title: 'Contacto', description: 'Cómo contactar con Histor.', sections: [{ p: ['Redacción y lectores: {{contact}}.', 'Protección de datos: {{dpo}}.', 'Para errores en una noticia, usa «Informar de un error»: así queda registrado y lo revisamos antes.'] }] },
    en: { title: 'Contact', description: 'How to contact Histor.', sections: [{ p: ['Newsroom and readers: {{contact}}.', 'Data protection: {{dpo}}.', 'For errors in a story, please use “Report an error” so it is logged and reviewed faster.'] }] },
